const input = $json.body ?? $json.query ?? $json;

const text = (value) => {
  if (value === null || value === undefined) return '';
  return String(value).trim();
};

const toBoolean = (value) => {
  if (typeof value === 'boolean') return value;
  return ['true', '1', 'yes', 'on'].includes(text(value).toLowerCase());
};

const clinic_name = text(input.clinic_name);
const status_filter = text(input.status_filter || 'active').toLowerCase();
const priority_filter = text(input.priority_filter || 'all').toLowerCase();
const task_type_filter = text(input.task_type_filter || 'all').toLowerCase();
const assigned_to = text(input.assigned_to);
const overdue_only = toBoolean(input.overdue_only);
const limit = Number(input.limit ?? 100);

const allowedStatuses = [
  'active',
  'open',
  'in_progress',
  'resolved',
  'cancelled',
  'all',
];

const allowedPriorities = [
  'urgent',
  'high',
  'normal',
  'low',
  'all',
];

const allowedTaskTypes = [
  'confirmation_no_response',
  'reschedule_request',
  'calendar_sync_issue',
  'medical_review',
  'complaint',
  'manual_followup',
  'all',
];

const errors = [];

if (!clinic_name) {
  errors.push({
    field: 'clinic_name',
    message: 'نام کلینیک الزامی است.',
  });
}

if (!allowedStatuses.includes(status_filter)) {
  errors.push({
    field: 'status_filter',
    message: 'فیلتر وضعیت معتبر نیست.',
  });
}

if (!allowedPriorities.includes(priority_filter)) {
  errors.push({
    field: 'priority_filter',
    message: 'فیلتر اولویت معتبر نیست.',
  });
}

if (!allowedTaskTypes.includes(task_type_filter)) {
  errors.push({
    field: 'task_type_filter',
    message: 'فیلتر نوع تسک معتبر نیست.',
  });
}

if (!Number.isInteger(limit) || limit < 1 || limit > 500) {
  errors.push({
    field: 'limit',
    message: 'limit باید یک عدد صحیح بین 1 و 500 باشد.',
  });
}

return [{
  json: {
    clinic_name,
    status_filter,
    priority_filter,
    task_type_filter,
    assigned_to,
    overdue_only,
    limit,
    validation_status: errors.length === 0 ? 'valid' : 'invalid',
    errors,
  },
}];

return [{
  json: {
    success: false,
    result: 'invalid_request',
    message: 'فیلترهای صف پیگیری ناقص یا نامعتبر است.',
    total_count: 0,
    handoff_tasks: [],
    errors: $json.errors ?? [],
  },
}];
